"use strict";(self.webpackChunksite=self.webpackChunksite||[]).push([["219"],{1625(e){e.exports=JSON.parse('{"version":{"pluginId":"england","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"lawsSidebar":[{"type":"link","href":"/codex-civica/laws/england/aep-1297-9","label":"Magna Carta (1297)","docId":"aep-1297-9","unlisted":false},{"type":"link","href":"/codex-civica/laws/england/aep-1677-3","label":"Statute of Frauds (1677)","docId":"aep-1677-3","unlisted":false},{"type":"link","href":"/codex-civica/laws/england/aep-1679-2","label":"Habeas Corpus Act 1679","docId":"aep-1679-2","unlisted":false},{"type":"link","href":"/codex-civica/laws/england/aep-1688-2","label":"Bill of Rights [1688]","docId":"aep-1688-2","unlisted":false},{"type":"link","href":"/codex-civica/laws/england/aep-1700-2","label":"Act of Settlement (1700)","docId":"aep-1700-2","unlisted":false},{"type":"link","href":"/codex-civica/laws/england/aep-1706-11","label":"Union with Scotland Act 1706","docId":"aep-1706-11","unlisted":false},{"type":"link","href":"/codex-civica/laws/england/","label":"Reading Guide","docId":"index","unlisted":false},{"type":"link","href":"/codex-civica/laws/england/ukpga-1911-13","label":"Parliament Act 1911","docId":"ukpga-1911-13","unlisted":false},{"type":"link","href":"/codex-civica/laws/england/ukpga-1911-6","label":"Perjury Act 1911","docId":"ukpga-1911-6","unlisted":false},{"type":"link","href":"/codex-civica/laws/england/ukpga-1949-103","label":"Parliament Act 1949","docId":"ukpga-1949-103","unlisted":false},{"type":"link","href":"/codex-civica/laws/england/ukpga-1959-66","label":"Obscene Publications Act 1959","docId":"ukpga-1959-66","unlisted":false},{"type":"link","href":"/codex-civica/laws/england/ukpga-1961-60","label":"Suicide Act 1961","docId":"ukpga-1961-60","unlisted":false},{"type":"link","href":"/codex-civica/laws/england/ukpga-1978-30","label":"Interpretation Act 1978","docId":"ukpga-1978-30","unlisted":false},{"type":"link","href":"/codex-civica/laws/england/ukpga-1988-27","label":"Malicious Communications Act 1988","docId":"ukpga-1988-27","unlisted":false},{"type":"link","href":"/codex-civica/laws/england/ukpga-1989-6","label":"Official Secrets Act 1989","docId":"ukpga-1989-6","unlisted":false},{"type":"link","href":"/codex-civica/laws/england/ukpga-1990-18","label":"Computer Misuse Act 1990","docId":"ukpga-1990-18","unlisted":false},{"type":"link","href":"/codex-civica/laws/england/ukpga-1998-42","label":"Human Rights Act 1998","docId":"ukpga-1998-42","unlisted":false},{"type":"link","href":"/codex-civica/laws/england/ukpga-2000-44","label":"Sexual Offences (Amendment) Act 2000","docId":"ukpga-2000-44","unlisted":false},{"type":"link","href":"/codex-civica/laws/england/ukpga-2010-23","label":"Bribery Act 2010","docId":"ukpga-2010-23","unlisted":false},{"type":"link","href":"/codex-civica/laws/england/ukpga-2011-14","label":"Fixed-term Parliaments Act 2011 (repealed)","docId":"ukpga-2011-14","unlisted":false},{"type":"link","href":"/codex-civica/laws/england/ukpga-2013-26","label":"Defamation Act 2013","docId":"ukpga-2013-26","unlisted":false}]},"docs":{"aep-1297-9":{"id":"aep-1297-9","title":"Magna Carta (1297)","description":"EDWARD by the Grace of God King of England, Lord of Ireland, and Duke of Guyan, [to all Archbishops, Bishops, &c.] We have seen the Great Charter of the Lord Henry sometimes King of England, our Father, of the Liberties of England in these words:","sidebar":"lawsSidebar"},"aep-1677-3":{"id":"aep-1677-3","title":"Statute of Frauds (1677)","description":"Reasons for passing this Act. For prevention of many fraudulent Practices which are commonly endeavoured to be upheld by Perjury and Subornation of Perjury.","sidebar":"lawsSidebar"},"aep-1679-2":{"id":"aep-1679-2","title":"Habeas Corpus Act 1679","description":"Recital that Delays had been used by Sheriffs in making Returns of Writs of Habeas Corpus, &c.WHEREAS great Delayes have beene used by Sheriffes Goalers and other Officers to whose Custody any of the Kings Subjects have beene committed for criminall or supposed criminall Matters in makeing Returnes of Writts of Habeas Corpus to them directed by standing out an Alias and Pluries Habeas Corpus and sometimes more and by other shifts to avoid their yeilding Obedience to such Writts contrary to their Duty and the knowne Lawes of the Land whereby many of the Kings Subjects have beene and hereafter may be long detained in Prison in such Cases where by Law they are baylable to their great charge and vexation.","sidebar":"lawsSidebar"},"aep-1688-2":{"id":"aep-1688-2","title":"Bill of Rights [1688]","description":"Whereas the Lords Spirituall and Temporall and Comons assembled at Westminster lawfully fully and freely representing all the Estates of the People of this Realme did upon the thirteenth day of February in the yeare of our Lord one thousand six hundred eighty eight present unto their Majesties then called and known by the Names and Stile of William and Mary Prince and Princesse of Orange being present in their proper Persons a certaine Declaration in Writeing made by the said Lords and Comons in the Words following vizThe Heads of Declaration of Lords and Commons, recited.Whereas the late King James the Second by the Assistance of diverse evill Councellors Judges and Ministers imployed by him did endeavour to subvert and extirpate the Protestant Religion and the Lawes and Liberties of this Kingdome. Dispensing and Suspending Power.By Assumeing and Exerciseing a Power of Dispensing with and Suspending of Lawes and the Execution of Lawes without Consent of Parlyament.Committing Prelates.By Committing and Prosecuting diverse Worthy Prelates for humbly Petitioning to be excused from Concurring to the said Assumed Power.Ecclesiastical Commission.By issueing and causeing to be executed a Commission under the Great Seale for Erecting a Court called The Court of Commissioners for Ecclesiasticall Causes.Levying Money.By Levying Money for and to the Use of the Crowne by pretence of Prerogative for other time and in other manner then the same was granted by Parlyament.Standing Army.By raising and keeping a Standing Army within this Kingdome in time of Peace without Consent of Parlyament and Quartering Soldiers contrary to Law.Disarming Protestants, &c.By causing severall good Subjects being Protestants to be disarmed at the same time when Papists were both Armed and Imployed contrary to Law.Violating Elections.By Violating the Freedome of Election of Members to serve in Parlyament. Illegal Prosecutions.By Prosecutions in the Court of Kings Bench for Matters and Causes cognizable onely in Parlyament and by diverse other Arbitrary and Illegall Courses. Juries.And whereas of late yeares Partiall Corrupt and Unqualifyed Persons have beene returned and served on Juryes in Tryalls and particularly diverse Jurors in Tryalls for High Treason which were not Freeholders,Excessive Bail.And excessive Baile hath beene required of Persons committed in Criminall Cases to elude the Benefitt of the Lawes made for the Liberty of the Subjects.Fines.And excessive Fines have beene imposed. Punishments.And illegall and cruell Punishments inflicted. Grants of Fines, &c. before Conviction, &c.And severall Grants and Promises made of Fines and Forfeitures before any Conviction or Judgement against the Persons upon whome the same were to be levyed. All which are utterly directly contrary to the knowne Lawes and Statutes and Freedome of this Realme.Recital that the late King James II. had abdicated the Government, and that the Throne was vacant, and that the Prince of Orange had written Letters to the Lords and Commons for the choosing Representatives in Parliament.And whereas the said late King James the Second haveing Abdicated the Government and the Throne being thereby Vacant His Hignesse the Prince of Orange (whome it hath pleased Almighty God to make the glorious Instrument of Delivering this Kingdome from Popery and Arbitrary Power) did (by the Advice of the Lords Spirituall and Temporall and diverse principall Persons of the Commons) cause Letters to be written to the Lords Spirituall and Temporall being Protestants and other Letters to the severall Countyes Cityes Universities Burroughs and Cinque Ports for the Choosing of such Persons to represent them as were of right to be sent to Parlyament to meete and sitt at Westminster upon the two and twentyeth day of January in this Yeare one thousand six hundred eighty and eight in order to such an Establishment as that their Religion Lawes and Liberties might not againe be in danger of being Subverted, Upon which Letters Elections haveing beene accordingly made. The Subject\u2019s Rights.And thereupon the said Lords Spirituall and Temporall and Commons pursuant to their respective Letters and Elections being now assembled in a full and free Representative of this Nation takeing into their most serious Consideration the best meanes for attaining the Ends aforesaid Doe in the first place (as their Auncestors in like Case have usually done) for the Vindicating and Asserting their auntient Rights and Liberties, DeclareDispensing Power.That the pretended Power of Suspending of Laws or the Execution of Laws by Regall Authority without Consent of Parlyament is illegall. Late dispensing Power.That the pretended Power of Dispensing with Laws or the Execution of Laws by Regall Authoritie as it hath beene assumed and exercised of late is illegall. Ecclesiastical Courts illegal.That the Commission for erecting the late Court of Commissioners for Ecclesiasticall Causes and all other Commissions and Courts of like nature are Illegall and Pernicious.Levying Money.That levying Money for or to the Use of the Crowne by pretence of Prerogative without Grant of Parlyament for longer time or in other manner then the same is or shall be granted is Illegall. Right to petition.That it is the Right of the Subjects to petition the King and all Commitments and Prosecutions for such Petitioning are Illegall. Standing Army.That the raising or keeping a standing Army within the Kingdome in time of Peace unlesse it be with Consent of Parlyament is against Law.Subjects\u2019 Arms.That the Subjects which are Protestants may have Arms for their Defence suitable to their Conditions and as allowed by Law. Freedom of Election.That Election of Members of Parlyament ought to be free. Freedom of Speech.That the Freedome of Speech and Debates or Proceedings in Parlyament ought not to be impeached or questioned in any Court or Place out of Parlyament.Excessive Bail.That excessive Baile ought not to be required nor excessive Fines imposed nor cruell and unusuall Punishments inflicted. Juries.That Jurors ought to be duely impannelled and returned . . .Grants of Forfeitures.That all Grants and Promises of Fines and Forfeitures of particular persons before Conviction are illegall and void. Frequent Parliaments.And that for Redresse of all Grievances and for the amending strengthening and preserveing of the Lawes Parlyaments ought to be held frequently.The said Rights claimed. Tender of the Crown. Regal Power exercised. Limitation of the Crown.And they doe Claime Demand and Insist upon all and singular the Premises as their undoubted Rights and Liberties and that noe Declarations Judgements Doeings or Proceedings to the Prejudice of the People in any of the said Premisses ought in any wise to be drawne hereafter into Consequence or Example. To which Demand of their Rights they are particularly encouraged by the Declaration of this Highnesse the Prince of Orange as being the onely meanes for obtaining a full Redresse and Remedy therein. Haveing therefore an intire Confidence That his said Highnesse the Prince of Orange will perfect the Deliverance soe farr advanced by him and will still preserve them from the Violation of their Rights which they have here asserted and from all other Attempts upon their Religion Rights and Liberties. The said Lords Spirituall and Temporall and Commons assembled at Westminster doe Resolve That William and Mary Prince and Princesse of Orange be and be declared King and Queene of England France and Ireland and the Dominions thereunto belonging to hold the Crowne and Royall Dignity of the said Kingdomes and Dominions to them the said Prince and Princesse dureing their Lives and the Life of the Survivour of them And that the sole and full Exercise of the Regall Power be onely in and executed by the said Prince of Orange in the Names of the said Prince and Princesse dureing their joynt Lives And after their Deceases the said Crowne and Royall Dignitie of the said Kingdoms and Dominions to be to the Heires of the Body of the said Princesse And for default of such Issue to the Princesse Anne of Denmarke and the Heires of her Body And for default of such Issue to the Heires of the Body of the said Prince of Orange. And the Lords Spirituall and Temporall and Commons doe pray the said Prince and () Princesse to accept the same accordingly.New Oaths of Allegiance, &c.And that the Oathes hereafter mentioned be taken by all Persons of whome the Oathes of Allegiance and Supremacy might be required by Law instead of them And that the said Oathes of Allegiance and Supremacy be abrogated.Allegiance.I A B doe sincerely promise and sweare That I will be faithfull and beare true Allegiance to their Majestyes King William and Queene Mary Soe helpe me God.Supremacy.I A B doe sweare That I doe from my Heart Abhorr, Detest and Abjure as Impious and Hereticall this damnable Doctrine and Position That Princes Excommunicated or Deprived by the Pope or any Authority of the See of Rome may be deposed or murdered by their Subjects or any other whatsoever. And I doe declare That noe Forreigne Prince Person Prelate, State or Potentate hath or ought to have any Jurisdiction Power Superiority Preeminence or Authoritie Ecclesiasticall or Spirituall within this Realme Soe helpe me God.Acceptance of the Crown. The Two Houses to sit. Subjects\u2019 Liberties to be allowed, and Ministers hereafter to serve according to the same. William and Mary declared King and Queen. Limitation of the Crown. Papists debarred the Crown. Every King, &c. shall make the Declaration of 30 Car. II. If under 12 Years old, to be done after Attainment thereof. King\u2019s and Queen\u2019s AssentUpon which their said Majestyes did accept the Crowne and Royall Dignitie of the Kingdoms of England France and Ireland and the Dominions thereunto belonging according to the Resolution and Desire of the said Lords and Commons contained in the said Declaration. And thereupon their Majestyes were pleased That the said Lords Spirituall and Temporall and Commons being the two Houses of Parlyament should continue to sitt and with their Majesties Royall Concurrence make effectuall Provision for the Setlement of the Religion Lawes and Liberties of this Kingdome soe that the same for the future might not be in danger againe of being subverted, To which the said Lords Spirituall and Temporall and Commons did agree and proceede to act accordingly. Now in pursuance of the Premisses the said Lords Spirituall and Temporall and Commons in Parlyament assembled for the ratifying confirming and establishing the said Declaration and the Articles Clauses Matters and Things therein contained by the Force of a Law made in due Forme by Authority of Parlyament doe pray that it may be declared and enacted That all and singular the Rights and Liberties asserted and claimed in the said Declaration are the true auntient and indubitable Rights and Liberties of the People of this Kingdome and soe shall be esteemed allowed adjudged deemed and taken to be and that all and every the particulars aforesaid shall be firmly and strictly holden and observed as they are expressed in the said Declaration And all Officers and Ministers whatsoever shall serve their Majestyes and their Successors according to the same in all times to come. And the said Lords Spirituall and Temporall and Commons seriously considering how it hath pleased Almighty God in his marvellous Providence and mercifull Goodness to this Nation to provide and preserve their said Majestyes Royall Persons most happily to Raigne over us upon the Throne of their Auncestors for which they render unto him from the bottome of their Hearts their humblest Thanks and Praises doe truely firmely assuredly and in the Sincerity of their Hearts thinke and doe hereby recognize acknowledge and declare That King James the Second haveing abdicated the Government and their Majestyes haveing accepted the Crowne and Royall Dignity as aforesaid Their said Majestyes did become were are and of right ought to be by the Lawes of this Realme our Soveraigne Liege Lord and Lady King and Queene of England France and Ireland and the Dominions thereunto belonging in and to whose Princely Persons the Royall State Crowne and Dignity of the said Realmes with all Honours Stiles Titles Regalities Prerogatives Powers Jurisdictions and Authorities to the same belonging and appertaining are most fully rightfully and intirely invested and incorporated united and annexed And for preventing all Questions and Divisions in this Realme by reason of any pretended Titles to the Crowne and for preserveing a Certainty in the Succession thereof in and upon which the Unity Peace Tranquillity and Safety of this Nation doth under God wholly consist and depend The said Lords Spirituall and Temporall and Commons doe beseech their Majestyes That it may be enacted established and declared That the Crowne and Regall Government of the said Kingdoms and Dominions with all and singular the Premisses thereunto belonging and appertaining shall bee and continue to their said Majestyes and the Survivour of them dureing their Lives and the Life of the Survivour of them And that the entire perfect and full Exercise of the Regall Power and Government be onely in and executed by his Majestie in the Names of both their Majestyes dureing their joynt Lives And after their deceases the said Crowne and Premisses shall be and remaine to the Heires of the Body of her Majestie and for default of such Issue to her Royall Highnesse the Princess Anne of Denmarke and the Heires of her Body and for default of such Issue to the Heires of the Body of his said Majestie And thereunto the said Lords Spirituall and Temporall and Commons doe in the Name of all the People aforesaid most humbly and faithfully submitt themselves their Heires and Posterities for ever and doe faithfully promise That they will stand to maintaine and defend their said Majesties and alsoe the Limitation and Succession of the Crowne herein specified and contained to the utmost of their Powers with their Lives and Estates against all Persons whatsoever that shall attempt any thing to the contrary. And whereas it hath beene found by Experience that it is inconsistent with the Safety and Welfaire of this Protestant Kingdome to be governed by a Popish Prince ... the said Lords Spirituall and Temporall and Commons doe further pray that it may be enacted That all and every person and persons that is are or shall be reconciled to or shall hold Communion with the See or Church of Rome or shall professe the Popish Religion ... shall be excluded and be for ever uncapeable to inherit possesse or enjoy the Crowne and Government of this Realme and Ireland and the Dominions thereunto belonging or any part of the same or to have use or exercise any Regall Power Authoritie or Jurisdiction within the same And in all and every such Case or Cases the People of these Realmes shall be and are hereby absolved of their Allegiance And the said Crowne and Government shall from time to time descend to and be enjoyed by such person or persons being Protestants as should have inherited and enjoyed the same in case the said person or persons soe reconciled holding Communion or Professing ... as aforesaid were naturally dead And that every King and Queene of this Realme who at any time hereafter shall come to and succeede in the Imperiall Crowne of this Kingdome shall on the first day of the meeting of the first Parlyament next after his or her comeing to the Crowne sitting in his or her Throne in the House of Peeres in the presence of the Lords and Commons therein assembled or at his or her Coronation before such person or persons who shall administer the Coronation Oath to him or her at the time of his or her takeing the said Oath (which shall first happen) make subscribe and audibly repeate the Declaration mentioned in the Statute made in the thirtyeth yeare of the Raigne of King Charles the Second Entituled An Act for the more effectuall Preserveing the Kings Person and Government by disableing Papists from sitting in either House of Parlyament But if it shall happen that such King or Queene upon his or her Succession to the Crowne of this Realme shall be under the Age of twelve yeares then every such King or Queene shall make subscribe and audibly repeate the said Declaration at his or her Coronation or the first day of the meeting of the first Parlyament as aforesaid which shall first happen after such King or Queene shall have attained the said Age of twelve yeares. All which Their Majestyes are contented and pleased shall be declared enacted and established by authoritie of this present Parliament and shall stand remaine and be the Law of this Realme for ever And the same are by their said Majesties by and with the advice and consent of the Lords Spirituall and Temporall and Commons in Parlyament assembled and by the authoritie of the same declared enacted and established accordingly","sidebar":"lawsSidebar"},"aep-1700-2":{"id":"aep-1700-2","title":"Act of Settlement (1700)","description":"Whereasin the First Year of the Reign of Your Majesty and of our late most gracious Sovereign Lady Queen Mary (of blessed Memory) An Act of Parliament was made intituled [An Act for declaring the Rights and Liberties of the Subject and for setling the Succession of the Crown] wherein it was (amongst other things) enacted established and declared That the Crown and Regall Government of the Kingdoms of England France and Ireland and the Dominions thereunto belonging should be and continue to Your Majestie and the said late Queen during the joynt Lives of Your Majesty and the said Queen and to the Survivor And that after the Decease of Your Majesty and of the said Queen the said Crown and Regall Government should be and remain to the Heirs of the Body of the said late Queen And for Default of such Issue to Her Royall Highness the Princess Ann of Denmark and the Heirs of Her Body And for Default of such Issue to the Heirs of the Body of Your Majesty And it was thereby further enacted That all and every Person and Persons that then were or afterwards should be reconciled to or shall hold Communion with the See or Church of Rome or should professe the Popish Religion ... should be excluded and are by that Act made for ever [incapable] to inherit possess or enjoy the Crown and Government of this Realm and Ireland and the Dominions thereunto belonging or any part of the same or to have use or exercise any regall Power Authority or Jurisdiction within the same And in all and every such Case and Cases the People of these Realms shall be and are thereby absolved of their Allegiance And that the said Crown and Government shall from time to time descend to and be enjoyed by such Person or Persons being Protestants as should have inherited and enjoyed the same in case the said Person or Persons so reconciled holding Communion professing ... as aforesaid were naturally dead After the making of which Statute and the Settlement therein contained Your Majesties good Subjects who were restored to the full and free Possession and Enjoyment of their [Religion] Rights and Liberties by the Providence of God giving Success to Your Majesties just Undertakings and unwearied Endeavours for that Purpose had no greater temporall Felicity to hope or wish for then to see a Royall Progeny descending from Your Majesty to whom (under God) they owe their Tranquility and whose Ancestors have for many Years been principall Assertors of the reformed Religion and the Liberties of [Europe] and from our said most gracious Sovereign Lady whose Memory will always be precious to the Subjects of these Realms And it having since pleased Almighty God to take away our said Sovereign Lady and also the most hopefull Prince William Duke of Gloucester (the only surviving Issue of Her Royall Highness the Princess Ann of Denmark) to the unspeakable Grief and Sorrow of Your Majesty and Your said good Subjects who under such Losses being sensibly put in mind that it standeth wholly in the Pleasure of Almighty God to prolong the Lives of Your Majesty and of Her Royall Highness and to grant to Your Majesty or to Her Royall Highness such Issue as may be inheritable to the Crown and Regall Government aforesaid by the respective Limitations in the said recited Act contained doe constantly implore the Divine Mercy for those Blessings And Your Majesties said Subjects having Daily Experience of Your Royall Care and Concern for the present and future Wellfare of these Kingdoms and particularly recommending from Your Throne a further Provision to be made for the Succession of the Crown in the Protestant Line for the Happiness of the Nation and the Security of our Religion And it being absolutely necessary for the Safety Peace and Quiet of this [Realm] to obviate all Doubts and Contentions in the same by reason of any pretended Titles to the [Crown] and to maintain a Certainty in the Succession thereof to which Your Subjects may safely have Recourse for their Protection in case the Limitations in the said recited [Act] should determine Therefore for a further Provision of the Succession of the Crown in the Protestant Line We Your Majesties most dutifull and Loyall Subjects the Lords Spirituall and Temporall and Commons in this present Parliament assembled do beseech Your Majesty that it may be enacted and declared and be it enacted and declared by the Kings most Excellent Majesty by and with the Advice and Consent of the Lords Spirituall and Temporall and Comons in this present Parliament assembled and by the Authority of the same That the most Excellent Princess Sophia Electress and Dutchess Dowager of Hannover Daughter of the most Excellent Princess Elizabeth late Queen of Bohemia Daughter of our late Sovereign Lord King James the First of happy Memory be and is hereby declared to be the next in Succession in the Protestant Line to the Imperiall Crown and Dignity of the [said] Realms of England France and Ireland with the Dominions and Territories thereunto belonging after His Majesty and the Princess Ann of Denmark and in Default of Issue of the said Princess Ann and of His Majesty respectively and that from and after the Deceases of His said Majesty our now Sovereign Lord and of Her Royall Highness the Princess Ann of Denmark and for Default of Issue of the said Princess Ann and of His Majesty respectively the Crown and Regall Government of the said Kingdoms of England France and Ireland and of the Dominions thereunto belonging with the Royall State and Dignity of the said Realms and all Honours Stiles Titles Regalities Prerogatives Powers Jurisdictions and Authorities to the same belonging and appertaining shall be remain and continue to the said most Excellent Princess Sophia and the Heirs of Her Body being Protestants And thereunto the said Lords Spirituall and Temporall and Commons shall and will in the Name of all the People of this Realm most humbly and faithfully submitt themselves their Heirs and Posterities and do faithfully promise That after the Deceases of His Majesty and Her Royall Highness and the failure of the Heirs of their respective Bodies to stand to maintain and defend the said Princess Sophia and the Heirs of Her Body being [Protestants] according to the Limitation and Succession of the Crown in this Act specified and contained to the utmost of their Powers with their Lives and Estates against all Persons whatsoever that shall attempt any thing to the contrary.","sidebar":"lawsSidebar"},"aep-1706-11":{"id":"aep-1706-11","title":"Union with Scotland Act 1706","description":"Most gracious SovereignRecital of Articles of Union, dated 22d July, 5 Ann.; and of an Act of Parliament passed in Scotland, 16th January, 5 Ann.Whereas Articles of Union were agreed on the Twenty Second day of July in the Fifth year of Your Majesties reign by the Commissioners nominated on behalf of the Kingdom of England under Your Majesties Great Seal of England bearing date at Westminster the Tenth day of April then last past in pursuance of an Act of Parliament made in England in the Third year of Your Majesties reign and the Commissioners nominated on the behalf of the Kingdom of Scotland under Your Majesties Great Seal of Scotland bearing date the Twenty Seventh day of February in the Fourth year of Your Majesties Reign in pursuance of the Fourth Act of the Third Session of the present Parliament of Scotland to treat of and concerning an Union of the said Kingdoms And Whereas an Act hath passed in the Parliament of Scotland at Edinburgh the Sixteenth day of January in the Fifth year of Your Majesties reign wherein \u2019tis mentioned that the Estates of Parliament considering the said Articles of Union of the two Kingdoms had agreed to and approved of the said Articles of Union with some Additions and Explanations And that Your Majesty with Advice and Consent of the Estates of Parliament for establishing the Protestant Religion and Presbyterian Church Government within the Kingdom of Scotland had passed in the same Session of Parliament an Act intituled Act for securing of the Protestant Religion and Presbyterian Church Government which by the Tenor thereof was appointed to be inserted in any Act ratifying the Treaty and expressly declared to be a fundamental and essential Condition of the said Treaty or Union in all times coming the Tenor of which Articles as ratified and approved of with Additions and Explanations by the said Act of Parliament of Scotland follows","sidebar":"lawsSidebar"},"index":{"id":"index","title":"Reading Guide","description":"England-applicable Acts of Parliament \u2014 source: legislation.gov.uk, the official UK legislation database, reused under the Open Government Licence v3.0.","sidebar":"lawsSidebar"},"ukpga-1911-13":{"id":"ukpga-1911-13","title":"Parliament Act 1911","description":"Whereas it is expedient that provision should be made for regulating the relations between the two Houses of ParliamentAnd whereas provision will require hereafter to be made by Parliament in a measure effecting such substitution for limiting and defining the powers of the new Second Chamber, but it is expedient to make such provision as in this Act appears for restricting the existing powers of the House of Lords:","sidebar":"lawsSidebar"},"ukpga-1911-6":{"id":"ukpga-1911-6","title":"Perjury Act 1911","description":"2 change(s) not yet applied to this Act. The source publisher (legislation.gov.uk) has recorded amendments that are not yet incorporated into the text below:","sidebar":"lawsSidebar"},"ukpga-1949-103":{"id":"ukpga-1949-103","title":"Parliament Act 1949","description":"The Parliament Act, 1911, shall have effect, and shall be deemed to have had effect from the beginning of the session in which the Bill for this Act originated (save as regards that Bill itself), as if\u2014","sidebar":"lawsSidebar"},"ukpga-1959-66":{"id":"ukpga-1959-66","title":"Obscene Publications Act 1959","description":"(1)","sidebar":"lawsSidebar"},"ukpga-1961-60":{"id":"ukpga-1961-60","title":"Suicide Act 1961","description":"[Extent \u2014 1. Suicide to cease to be a crime.] E+W","sidebar":"lawsSidebar"},"ukpga-1978-30":{"id":"ukpga-1978-30","title":"Interpretation Act 1978","description":"1 change(s) not yet applied to this Act. The source publisher (legislation.gov.uk) has recorded amendments that are not yet incorporated into the text below:","sidebar":"lawsSidebar"},"ukpga-1988-27":{"id":"ukpga-1988-27","title":"Malicious Communications Act 1988","description":"Be it enacted by the Queen\u2019s most Excellent Majesty, by and with the advice and consent of the Lords Spiritual and Temporal, and Commons, in this present Parliament assembled, and by the authority of the same, as follows:\u2014","sidebar":"lawsSidebar"},"ukpga-1989-6":{"id":"ukpga-1989-6","title":"Official Secrets Act 1989","description":"1 change(s) not yet applied to this Act. The source publisher (legislation.gov.uk) has recorded amendments that are not yet incorporated into the text below:","sidebar":"lawsSidebar"},"ukpga-1990-18":{"id":"ukpga-1990-18","title":"Computer Misuse Act 1990","description":"2 change(s) not yet applied to this Act. The source publisher (legislation.gov.uk) has recorded amendments that are not yet incorporated into the text below:","sidebar":"lawsSidebar"},"ukpga-1998-42":{"id":"ukpga-1998-42","title":"Human Rights Act 1998","description":"5 change(s) not yet applied to this Act. The source publisher (legislation.gov.uk) has recorded amendments that are not yet incorporated into the text below:","sidebar":"lawsSidebar"},"ukpga-2000-44":{"id":"ukpga-2000-44","title":"Sexual Offences (Amendment) Act 2000","description":"Be it enacted by the Queen\u2019s most Excellent Majesty, by and with the advice and consent of the Commons in this present Parliament assembled, in accordance with the provisions of the Parliament Acts 1911 and 1949, and by the authority of the same, as follows:\u2014","sidebar":"lawsSidebar"},"ukpga-2010-23":{"id":"ukpga-2010-23","title":"Bribery Act 2010","description":"Be it enacted by the Queen\'s most Excellent Majesty, by and with the advice and consent of the Lords Spiritual and Temporal, and Commons, in this present Parliament assembled, and by the authority of the same, as follows:\u2014","sidebar":"lawsSidebar"},"ukpga-2011-14":{"id":"ukpga-2011-14","title":"Fixed-term Parliaments Act 2011 (repealed)","description":". . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .","sidebar":"lawsSidebar"},"ukpga-2013-26":{"id":"ukpga-2013-26","title":"Defamation Act 2013","description":"Be it enacted by the Queen\'s most Excellent Majesty, by and with the advice and consent of the Lords Spiritual and Temporal, and Commons, in this present Parliament assembled, and by the authority of the same, as follows:\u2014","sidebar":"lawsSidebar"}}}}')}}]);